use Iterator;
use Throwable;
use Civi\Lughauth\Features\Access\User\Application\Service\Visibility\UserVisibilityService;
use Civi\Lughauth\Features\Access\RelyingParty\Application\Service\Visibility\RelyingPartyVisibilityService;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Service\Visibility\TrustedClientVisibilityService;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesListRef;
use Civi\Lughauth\Features\Access\Role\Application\Service\Visibility\RoleVisibilityService;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\PlatformIdentityRef;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\PlatformIdentityAttributes;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\PlatformIdentity;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityFilter;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityCursor;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityReadGateway;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentitySlide;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class PlatformIdentityVisibilityService
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly PlatformIdentityReadGateway $readGateway,
        private readonly PlatformIdentityWriteGateway $writeGateway,
        private readonly UserVisibilityService $userVisibilityService,
        private readonly RelyingPartyVisibilityService $relyingPartyVisibilityService,
        private readonly TrustedClientVisibilityService $trustedClientVisibilityService,
        private readonly RoleVisibilityService $roleVisibilityService
    ) {
    }

    public function prepareVisibleDataInList(PlatformIdentity $content): PlatformIdentityAttributes
    {
        return $this->prepareVisibleDataCallback($content, true);
    }
    public function prepareVisibleData(PlatformIdentity $content): PlatformIdentityAttributes
    {
        return $this->prepareVisibleDataCallback($content, false);
    }
    public function copyWithFixed(PlatformIdentityAttributes $attributes, ?PlatformIdentity $original = null): PlatformIdentityAttributes
    {
        $this->logDebug("Copy with fixed for Platform identity");
        $span = $this->startSpan("Copy with fixed for  Platform identity");
        try {
            $visible = $this->visiblesReferences($attributes);
            $fixed = $this->fieldsToFix($original);
            foreach ($fixed as $field) {
                $visible->unset($field);
            }
            $result = $this->dispatcher->dispatch(new PlatformIdentityPresetValues($attributes, $original));
            return $result->attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function copyWithHidden(PlatformIdentityAttributes $attributes, ?PlatformIdentity $original = null): PlatformIdentityAttributes
    {
        $this->logDebug("Copy with hidden for Platform identity");
        $span = $this->startSpan("Copy with hidden for  Platform identity");
        try {
            $hidden = $this->fieldsToHide($original);
            foreach ($hidden as $field) {
                $attributes->unset($field);
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function checkVisibility(Iterator|string|PlatformIdentityRef $value): bool
    {
        $this->logDebug("Check visibility of an iterator for Platform identity");
        $span = $this->startSpan("Check visibility of an iterator for  Platform identity");
        try {
            if (is_string($value)) {
                return !!$this->retrieveVisibleForUpdate(new PlatformIdentityRef($value));
            } elseif ($value instanceof PlatformIdentityRef) {
                return !!$this->retrieveVisibleForUpdate($value);
            } elseif ($value instanceof Iterator) {
                $ids = [];
                foreach ($value as $val) {
                    $ids[] = $val->uid();
                }
                $filter = new PlatformIdentityFilter(uids: $ids);
                return count($ids) == $this->countVisibles($filter);
            } else {
                return false;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisibles(PlatformIdentityFilter $filter, ?PlatformIdentityCursor $cursor = null): PlatformIdentitySlide
    {
        $this->logDebug("List visibles for Platform identity");
        $span = $this->startSpan("List visibles for  Platform identity");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->readGateway->list($visibleFilter, $cursor);
            return $result->slide(function (PlatformIdentity $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisibles(PlatformIdentityFilter $filter): int
    {
        $this->logDebug("Count visibles for Platform identity");
        $span = $this->startSpan("Count visibles for  Platform identity");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->readGateway->count($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function listVisiblesForUpdate(PlatformIdentityFilter $filter, ?PlatformIdentityCursor $cursor = null): PlatformIdentitySlide
    {
        $this->logDebug("List visibles for update for Platform identity");
        $span = $this->startSpan("List visibles for update for  Platform identity");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            $result = $this->writeGateway->listForUpdate($visibleFilter, $cursor);
            return $result->slide(function (PlatformIdentity $item): bool {
                return $this->evaluatePostVisibility($item);
            });
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function countVisiblesForUpdate(PlatformIdentityFilter $filter): int
    {
        $this->logDebug("Count visibles for update for Platform identity");
        $span = $this->startSpan("Count visibles for update for  Platform identity");
        try {
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            return $this->writeGateway->countForUpdate($visibleFilter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisible(PlatformIdentityRef $ref): ?PlatformIdentity
    {
        $this->logDebug("Retrieve visible for Platform identity");
        $span = $this->startSpan("Retrieve visible for  Platform identity");
        try {
            $filter = new PlatformIdentityFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->readGateway->retrieve($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieveVisibleForUpdate(PlatformIdentityRef $ref): ?PlatformIdentity
    {
        $this->logDebug("Retrieve visible for update for Platform identity");
        $span = $this->startSpan("Retrieve visible for update for  Platform identity");
        try {
            $filter = new PlatformIdentityFilter(uids: [$ref->uid()]);
            $visibleFilter = $this->applyPreVisibilityFilter($filter);
            if ($readed = $this->writeGateway->retrieveForUpdate($visibleFilter)) {
                return $this->evaluatePostVisibility($readed) ? $readed : null;
            } else {
                return null;
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fieldsToFix(?PlatformIdentityRef $ref = null): array
    {
        $this->logDebug("Check fields to fix for Platform identity");
        $span = $this->startSpan("Check fields for fix for Platform identity");
        try {
            $result = $this->dispatcher->dispatch(new PlatformIdentityCollectNonEditableFields(PlatformIdentity::calculatedFields(), $ref));
            return array_values(array_unique(array_merge($this->fieldsToHide($ref), $result->fields)));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    public function fieldsToHide(?PlatformIdentityRef $ref = null): array
    {
        $this->logDebug("Check fields to hide for Platform identity");
        $span = $this->startSpan("Check fields to hide for  Platform identity");
        try {
            $result = $this->dispatcher->dispatch(new PlatformIdentityCollectNonVisibleFields([], $ref));
            return array_values(array_unique($result->fields));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function visiblesReferences(PlatformIdentityAttributes $attributes): PlatformIdentityAttributes
    {
        $this->logDebug("Check visibility of parent references for Platform identity");
        $span = $this->startSpan("Check visibility of parent references for  Platform identity");
        try {
            $user = $attributes->getUser();
            if (null !== $user && !$this->userVisibilityService->checkVisibility($user)) {
                throw new NotFoundException("Unknown User " . ($user->uid() ?? 'no-id'));
            }
            $relyingParty = $attributes->getRelyingParty();
            if (null !== $relyingParty && !$this->relyingPartyVisibilityService->checkVisibility($relyingParty)) {
                throw new NotFoundException("Unknown RelyingParty " . ($relyingParty->uid() ?? 'no-id'));
            }
            $trustedClient = $attributes->getTrustedClient();
            if (null !== $trustedClient && !$this->trustedClientVisibilityService->checkVisibility($trustedClient)) {
                throw new NotFoundException("Unknown TrustedClient " . ($trustedClient->uid() ?? 'no-id'));
            }
            $roles = $attributes->getRoles();
            if (null !== roles && !$this->checkVisibilityForRoles($roles)) {
                throw new NotFoundException("Unknown Roles " . ($roles->uid() ?? 'no-id'));
            }
            return $attributes;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function applyPreVisibilityFilter(PlatformIdentityFilter $filter): PlatformIdentityFilter
    {
        $this->logDebug("Compose visibility filter for Platform identity");
        $span = $this->startSpan("Compose visibility filter for  Platform identity");
        try {
            $result = $this->dispatcher->dispatch(new PlatformIdentityRestrictFilterToVisibility($filter));
            return $result->platformIdentityFilter;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function checkVisibilityForRoles(PlatformIdentityRolesListRef $items): PlatformIdentityRolesListRef
    {
        $this->logDebug("Copy with fixed for Platform identity");
        $span = $this->startSpan("Copy with fixed for  Platform identity");
        try {
            foreach ($items as $item) {
                if ($item->getRole() && !$this->roleVisibilityService->checkVisibility($item->getRole())) {
                    throw new NotFoundException("Unknown Role " . $item->getRole()->uid());
                }
            }
            return $items;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function evaluatePostVisibility(PlatformIdentity $value): bool
    {
        $this->logDebug("Check if item is visible for Platform identity");
        $span = $this->startSpan("Check if item is visible for  Platform identity");
        try {
            $result = $this->dispatcher->dispatch(new PlatformIdentityVisibilityCheck(true, $value));
            return $result->visible;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function prepareVisibleDataCallback(PlatformIdentity $content, bool $inlist): PlatformIdentityAttributes
    {
        $this->logDebug("Prepare hydration to visible data for Platform identity");
        $span = $this->startSpan("Prepare hydration to visible data for Platform identity");
        try {
            $attributes = $content->toAttributes();
            $result = $this->dispatcher->dispatch(new PlatformIdentityEnrichForView($content, $inlist, $attributes));
            return $result->getAttributes();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
